webpack can't find the file\n// and the build fails.\n// See https://webpack.js.org/guides/package-exports/ for more information on how webpack uses\n// the 'exports' field.\n@import \"~react-loading-skeleton/dist/skeleton.css\";\n@import \"~bootstrap/scss/transitions\";\n@import \"utilities\";\n@import \"~bootstrap/scss/media\";\n@import \"~bootstrap/scss/list-group\";\n@import \"~bootstrap/scss/print\";\n\n// Paragon components\n@import \"../../src/index\";\n","// Variables\n//\n// Variables should follow the `$component-state-property-size` formula for\n// consistent naming. Ex: $nav-link-disabled-color and $modal-content-box-shadow-xs.\n@import \"exports.module.scss\";\n\n// Color system\n$white:    #FFFFFF !default;\n$gray-100: #EBEBEB !default;\n$gray-200: #CCCCCC !default;\n$gray-300: #ADADAD !default;\n$gray-400: #8F8F8F !default;\n$gray-500: #707070 !default;\n$gray-600: #5C5C5C !default;\n$gray-700: #454545 !default;\n$gray-800: #333333 !default;\n$gray-900: #212529 !default;\n$black:    #000000 !default;\n\n$grays: () !default;\n$grays: map-merge(\n  (\n    \"100\": $gray-100,\n    \"200\": $gray-200,\n    \"300\": $gray-300,\n    \"400\": $gray-400,\n    \"500\": $gray-500,\n    \"600\": $gray-600,\n    \"700\": $gray-700,\n    \"800\": $gray-800,\n    \"900\": $gray-900\n  ),\n  $grays\n);\n\n$blue: #23419F !default;\n$red: #C32D3A !default;\n$yellow: #FFD900 !default;\n$green: #178253 !default;\n$teal: #006DAA !default;\n\n$colors: () !default;\n$colors: map-merge(\n  (\n    \"blue\": $blue,\n    \"green\": $green,\n    \"teal\": $teal,\n    \"red\": $red,\n    \"yellow\": $yellow,\n    \"white\": $white,\n    \"gray\": $gray-500,\n    \"dark-gray\": $gray-700,\n  ),\n  $colors\n);\n\n$primary: #0A3055 !default;\n$secondary: $gray-700 !default;\n$brand: #9D0054 !default;\n$success: $green !default;\n$info: $teal !default;\n$danger: $red !default;\n$warning: $yellow !default;\n$light: #E1DDDB !default;\n$dark: #273F2F !default;\n$accent-a: #00BBF9 !defa